 }

 main table thead th {
 position: relative;
 background: rgb(248 250 252);
 color: rgb(71 85 105);
 font-size: .72rem;
 font-weight: 700;
 letter-spacing: .01em;
 line-height: 1.45;
 white-space: nowrap;
 }

 main table tbody tr {
 transition: background-color .12s ease, box-shadow .12s ease;
 }

 main table tbody tr:hover {
