 font-variant-numeric: tabular-nums;
 }

 :where(code,
 kbd,
 samp,
 [dir="ltr"]) {
 direction: ltr;
 unicode-bidi: isolate;
 }

 main :where(button,
 a)[class*="bg-blue-600"] {
